// SPEC LINK: docs/specs/01-pipeline/124_step_standard_policy.md §5 R-GU, R-GV, R-GW, R-GX (operator y 2026-10-20)
//
// Spec 132 and the spec roles (operator 2026-10-20, "y to both" and "y to this revised version"):
//   R-GU  the step handbook is Spec 132 — Step Standard Handbook, generated by scripts/generate-step-handbook.mjs;
//         a line is cited as `Spec 132 §<line id> (R-xx)`, and spec-split-check resolves every such citation and
//         checks the named rule maps to that line. A generated spec has no hand-written line budget; it has a size
//         cap (122_split_manifest.json generated_size_caps).
//   R-GV  standard + policy pairs: Spec 122 (standard) + Spec 124 (policy register). On policy the 124 register
//         governs; on schema and behaviour Spec 122 governs (Spec 124's header no longer says 122 governs on conflict).
//   R-GW  every spec in docs/specs carries one role banner: authority register / standard / design / historical /
//         generated handbook.
//   R-GX  the lock: every spec has a role banner (or sits on the closed, shrink-only role_banner_pending list), and a
//         spec whose role is historical introduces no new rule id (spec-split-check arm (vii)).
// Citation strings below are built by concatenation so the arm (iii) census of this file never sees a fake one.

import { describe, expect, it, beforeAll } from 'vitest';
import { spawnSync } from 'node:child_process';
import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';
import { pathToFileURL } from 'node:url';

const REPO_ROOT = path.resolve(__dirname, '../../');
const SPEC_DIR = path.join(REPO_ROOT, 'docs/specs/01-pipeline');
const CHECKER = path.join(REPO_ROOT, 'scripts/analysis/spec-split-check.mjs');
const MANIFEST_PATH = path.join(SPEC_DIR, '122_split_manifest.json');
const RULE_MAP_PATH = path.join(REPO_ROOT, 'scripts/steps/_schema/rule-map.json');
const SPEC_132_REL = 'docs/specs/01-pipeline/132_step_standard_handbook.md';
const SPEC_122A_REL = 'docs/specs/01-pipeline/122a_step_optimization_appendix.md';
const read = (rel: string) => fs.readFileSync(path.join(REPO_ROOT, rel), 'utf8');

type Problem = string;
type Citation = { citation: string; kind: string; lineId: string; rules: string[]; file: string; line: number };
type Checker = {
  SPEC_FILES: Record<string, string>;
  ROLE_VOCAB: readonly string[];
  extractRoleBanners: (text: string) => string[];
  collectSpecDocs: () => Array<{ rel: string; text: string }>;
  checkSpecRoles: (specs: Array<{ rel: string; text: string }>, manifest: unknown, ruleMap: unknown) => Problem[];
  checkGeneratedSizeCaps: (texts: Record<string, string>, manifest: unknown) => Problem[];
  extractHandbookCitations: (text: string, file?: string) => Citation[];
  checkHandbookCitations: (citations: Citation[], ruleMap: unknown) => Problem[];
};
type Gen = { render: (map: unknown, defectLines: Map<string, number>) => string };
type RuleMapMod = { HANDBOOK_REL: string; loadRuleMap: () => { meta: Record<string, unknown>; rules: Array<{ id: string; handbook_line: string; source: Record<string, unknown> }> }; readDefectLines: () => Map<string, number> };

let ck: Checker;
let rm: RuleMapMod;
let gen: Gen;
beforeAll(async () => {
  ck = (await import(pathToFileURL(CHECKER).href)) as unknown as Checker;
  rm = (await import(pathToFileURL(path.join(REPO_ROOT, 'scripts/analysis/gates/rule-map.mjs')).href)) as unknown as RuleMapMod;
  gen = (await import(pathToFileURL(path.join(REPO_ROOT, 'scripts/generate-step-handbook.mjs')).href)) as unknown as Gen;
});

const manifest = () => JSON.parse(fs.readFileSync(MANIFEST_PATH, 'utf8')) as Record<string, unknown> & {
  budgets: Record<string, unknown>;
  generated_size_caps: Record<string, { max_lines: number; max_bytes: number; why: string }>;
  role_banner_pending: string[];
  historical_rule_ids: Record<string, string[]>;
};
const ruleMap = () => JSON.parse(fs.readFileSync(RULE_MAP_PATH, 'utf8')) as { meta: Record<string, unknown>; rules: Array<{ id: string; handbook_line: string; status: string; source: Record<string, unknown> }> };
const cite132 = (line: string, rules = '') => `Spec 132 ${'§'}${line}${rules ? ` (${rules})` : ''}`;

describe('R-GU — the step handbook is Spec 132, generated', () => {
  it('the generator writes docs/specs/01-pipeline/132_step_standard_handbook.md and the committed file is current', () => {
    expect(rm.HANDBOOK_REL).toBe(SPEC_132_REL);
    expect(read(SPEC_132_REL)).toBe(gen.render(rm.loadRuleMap(), rm.readDefectLines()));
  });

  it('carries a spec header: title, a Status line, the role banner, the authority sentence and the citation form', () => {
    const text = read(SPEC_132_REL);
    expect(text.split('\n')[0]).toBe('# SPEC 132 — Step Standard Handbook');
    expect(text).toMatch(/^\*\*Status:\*\* GENERATED$/m);
    expect(ck.extractRoleBanners(text)).toEqual(['generated handbook']);
    expect(text).toContain('Authority: Spec 124 register (policy) + Spec 122 (schema); this spec is GENERATED from rule-map.json — do not hand-edit');
    expect(text).toContain('`Spec 132 §<line id> (R-xx)`');
    // The worked example in the header is a real line and a real rule that maps to it.
    const ex = /e\.g\. `(Spec 132 §[^`]+)`/.exec(text);
    expect(ex).not.toBeNull();
    expect(ck.checkHandbookCitations(ck.extractHandbookCitations(ex![1]!), ruleMap())).toEqual([]);
  });

  it('the old path is a pointer to Spec 132, not a second generated copy', () => {
    const old = read('docs/handbook/step-standard.md');
    expect(old).toContain(SPEC_132_REL);
    expect(old).not.toContain('GENERATED by');
    expect(old.split('\n').length).toBeLessThan(12);
  });

  it('RED/GREEN — a `Spec 132 §<line id> (R-xx)` citation resolves only to a real line its rule maps to', () => {
    const map = ruleMap();
    const r = map.rules.find((x) => x.id === 'R-GU')!;
    const good = ck.extractHandbookCitations(`see ${cite132(r.handbook_line, 'R-GU')} and ${cite132('core.1')}`);
    expect(good.map((c) => c.lineId)).toEqual([r.handbook_line, 'core.1']);
    expect(ck.checkHandbookCitations(good, map)).toEqual([]);
    const noLine = ck.checkHandbookCitations(ck.extractHandbookCitations(cite132('core.999')), map);
    expect(noLine.join(' ')).toMatch(/core\.999 is not a handbook line/);
    const wrongRule = ck.checkHandbookCitations(ck.extractHandbookCitations(cite132('core.1', 'R-GU')), map);
    expect(wrongRule.join(' ')).toMatch(/R-GU maps to x-rulings\.3, not core\.1/);
    const unknown = ck.checkHandbookCitations(ck.extractHandbookCitations(cite132('core.1', 'R-ZZZ')), map);
    expect(unknown.join(' ')).toMatch(/R-ZZZ is not a rule-map id/);
  });

  it('RED/GREEN — Spec 132 has a size cap, not a hand-written line budget', () => {
    const m = manifest();
    expect(m.budgets['132']).toBeUndefined();
    const cap = m.generated_size_caps['132']!;
    expect(cap.why.length).toBeGreaterThan(40);
    const text = read(SPEC_132_REL);
    // Spec 133's cap (R-IY) is checked in spec133-bylaw-handbook.logic; this fixture holds Spec 132's alone.
    const only132 = { ...m, generated_size_caps: { '132': cap } };
    expect(ck.checkGeneratedSizeCaps({ '132': text }, only132)).toEqual([]);
    const tight = { ...m, generated_size_caps: { '132': { ...cap, max_bytes: 10 } } };
    expect(ck.checkGeneratedSizeCaps({ '132': text }, tight).join(' ')).toMatch(/SIZE CAP spec 132/);
    const both = { ...m, generated_size_caps: { '132': cap }, budgets: { ...m.budgets, '132': { headroom_pct: 10, measured_at: { lines: 1, bytes: 1, commit: 'x' } } } };
    expect(ck.checkGeneratedSizeCaps({ '132': text }, both).join(' ')).toMatch(/generated spec 132 also has a hand-written budget/);
    expect(ck.SPEC_FILES['132']).toBe('132_step_standard_handbook.md');
  });
});

describe('R-GV — standard + policy pairs; the Spec 124 transition clause is flipped', () => {
  it('Spec 124 says the register governs on policy and Spec 122 on schema and behaviour, citing R-GV', () => {
    const header = read('docs/specs/01-pipeline/124_step_standard_policy.md').split('\n').slice(0, 16).join('\n');
    expect(header).not.toContain('On conflict during the transition, Spec 122 governs');
    expect(header).toMatch(/On a policy question this register governs; on the schema and behaviour, Spec 122 governs \(R-GV\)/);
  });

  it('the rule map names both halves as the authority and no longer lists Spec 122 as historical', () => {
    const meta = ruleMap().meta as { authority: string; historical_design_records: string[]; reading_surface: string };
    expect(meta.authority).toMatch(/Spec 124 register.*\+ Spec 122/);
    expect(meta.historical_design_records).not.toContain('Spec 122');
    expect(meta.historical_design_records).toContain('Spec 122a');
    expect(meta.reading_surface).toContain(SPEC_132_REL);
  });
});

describe('R-GW — one role banner per spec', () => {
  it('122 standard, 122a historical, 124 and 124a authority register, 132 generated handbook', () => {
    const roles = (f: string) => ck.extractRoleBanners(fs.readFileSync(path.join(SPEC_DIR, f), 'utf8'));
    expect(roles('122_pipeline_step_optimization.md')).toEqual(['standard']);
    expect(roles('122a_step_optimization_appendix.md')).toEqual(['historical']);
    expect(roles('124_step_standard_policy.md')).toEqual(['authority register']);
    expect(roles('124a_step_standard_policy_appendix.md')).toEqual(['authority register']);
    expect(roles('132_step_standard_handbook.md')).toEqual(['generated handbook']);
    expect([...ck.ROLE_VOCAB]).toEqual(['authority register', 'standard', 'design', 'historical', 'generated handbook']);
  });
});

describe('R-HH, R-HI, R-HJ — the roles of Specs 120, 121 and 123 (operator "y" 2026-10-20)', () => {
  const SPEC_120_REL = 'docs/specs/01-pipeline/120_pipeline_step_runner.md';
  const SPEC_121_REL = 'docs/specs/01-pipeline/121_assessment_and_verification_methodology.md';
  const SPEC_123_REL = 'docs/specs/01-pipeline/123_step_opt_assessment_validation.md';

  it('R-HH: Spec 120 is historical: one banner, the incident as a dated note, Status HISTORICAL, an empty baseline', () => {
    const text = read(SPEC_120_REL);
    expect(ck.extractRoleBanners(text)).toEqual(['historical']);
    expect(text).toMatch(/^\*\*Status:\*\* HISTORICAL/m);
    expect(text).not.toContain('NOT RATIFIED — the line that stood here was false');
    expect(text).toContain('*Dated note 2026-10-20 (Spec 124 R-HH; operator "y"):*');
    expect(text).toContain('"the specs are good ratify"');
    expect(text).toContain('✅ RATIFIED 2026-08-22 — registered by operator authorization');
    expect(manifest().historical_rule_ids[SPEC_120_REL]).toEqual([]);
  });

  it('R-HI: Spec 121 is historical with the retired M1–M14 as its baseline', () => {
    const text = read(SPEC_121_REL);
    expect(ck.extractRoleBanners(text)).toEqual(['historical']);
    expect(text).toMatch(/^\*\*Status:\*\* HISTORICAL/m);
    expect(text).toContain('(Spec 124 R-HI; operator "y")');
    expect([...manifest().historical_rule_ids[SPEC_121_REL]!].sort()).toEqual(Array.from({ length: 14 }, (_, i) => `M${i + 1}`).sort());
  });

  it('R-HJ: Spec 123 is a standard; Spec 121 no longer governs it; it leaves historical_design_records', () => {
    const text = read(SPEC_123_REL);
    expect(ck.extractRoleBanners(text)).toEqual(['standard']);
    expect(text).not.toContain('GOVERNS this document');
    expect(text).toContain('**Spec 121 is the historical method record this procedure instantiates**');
    const meta = ruleMap().meta as { historical_design_records: string[]; precedence: string };
    expect(meta.historical_design_records).toEqual(['Spec 119', 'Spec 120', 'Spec 121', 'Spec 122a']);
    expect(meta.precedence).toContain('Spec 123 is the standard for the conversion procedure and its G0–G9 gates (R-HJ)');
  });

  it('none of the three is still on role_banner_pending (the list shrank by three)', () => {
    const pending = manifest().role_banner_pending;
    for (const rel of [SPEC_120_REL, SPEC_121_REL, SPEC_123_REL]) expect(pending).not.toContain(rel);
  });
});

describe('R-GX — the role lock (spec-split-check arm vii)', () => {
  const specs = () => ck.collectSpecDocs();

  it('GREEN — the committed tree: every spec has one banner or is pending, and no historical spec adds a rule id', () => {
    const all = specs();
    expect(all.length).toBeGreaterThan(100);
    expect(ck.checkSpecRoles(all, manifest(), ruleMap())).toEqual([]);
  });

  it('RED — a spec with no banner that is not on the pending list', () => {
    const m = manifest();
    const victim = m.role_banner_pending[0]!;
    const red = ck.checkSpecRoles(specs(), { ...m, role_banner_pending: m.role_banner_pending.slice(1) }, ruleMap());
    expect(red.join('\n')).toContain(`${victim}: no role banner`);
  });

  it('RED — a pending spec that now has a banner must leave the list (shrink-only); an unknown role; two banners', () => {
    const m = manifest();
    const victim = m.role_banner_pending[0]!;
    const withBanner = specs().map((s) => (s.rel === victim ? { ...s, text: `${s.text}\n> **Role: design.** fixture\n` } : s));
    expect(ck.checkSpecRoles(withBanner, m, ruleMap()).join('\n')).toContain(`${victim}: has a role banner — remove it from role_banner_pending`);
    const badRole = specs().map((s) => (s.rel === SPEC_122A_REL ? { ...s, text: s.text.replace('> **Role: historical.**', '> **Role: archive.**') } : s));
    expect(ck.checkSpecRoles(badRole, m, ruleMap()).join('\n')).toContain(`${SPEC_122A_REL}: role "archive" is not in the vocabulary`);
    const two = specs().map((s) => (s.rel === SPEC_122A_REL ? { ...s, text: `${s.text}\n> **Role: standard.** fixture\n` } : s));
    expect(ck.checkSpecRoles(two, m, ruleMap()).join('\n')).toContain(`${SPEC_122A_REL}: 2 role banners`);
  });

  it('RED — a historical spec introduces a new rule id (a rule-map id sourced to it, or a register-shaped row)', () => {
    const m = manifest();
    const map = ruleMap();
    const extra = { ...map, rules: [...map.rules, { ...map.rules.find((r) => r.id === 'V1')!, id: 'V9' }] };
    expect(ck.checkSpecRoles(specs(), m, extra).join('\n')).toContain(`${SPEC_122A_REL}: new rule id V9 in a historical spec`);
    const row = specs().map((s) => (s.rel === SPEC_122A_REL ? { ...s, text: `${s.text}\n| R-ZQ | a new rule | x |\n` } : s));
    expect(ck.checkSpecRoles(row, m, map).join('\n')).toContain(`${SPEC_122A_REL}: new rule id R-ZQ in a historical spec`);
  });

  it('RED — a historical spec with no baseline, and a stale baseline id (the baseline only shrinks)', () => {
    const m = manifest();
    const noBase = { ...m, historical_rule_ids: {} };
    expect(ck.checkSpecRoles(specs(), noBase, ruleMap()).join('\n')).toContain(`${SPEC_122A_REL}: historical spec has no historical_rule_ids baseline`);
    const stale = { ...m, historical_rule_ids: { ...m.historical_rule_ids, [SPEC_122A_REL]: [...m.historical_rule_ids[SPEC_122A_REL]!, 'V99'] } };
    expect(ck.checkSpecRoles(specs(), stale, ruleMap()).join('\n')).toContain(`${SPEC_122A_REL}: baseline id V99 no longer appears — remove it`);
  });

  it('RED via the real CLI — a register row added to 122a on a fixture tree fails --check arm (vii)', () => {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'spec132-roles-'));
    for (const file of Object.values(ck.SPEC_FILES)) fs.copyFileSync(path.join(SPEC_DIR, file), path.join(dir, file));
    fs.copyFileSync(MANIFEST_PATH, path.join(dir, '122_split_manifest.json'));
    const env = {
      ...process.env,
      BUILDO_SPEC_SPLIT_SPEC_DIR: path.relative(REPO_ROOT, dir),
      BUILDO_SPEC_SPLIT_MANIFEST_PATH: path.relative(REPO_ROOT, path.join(dir, '122_split_manifest.json')),
    };
    const ok = spawnSync('node', [CHECKER, '--check'], { cwd: REPO_ROOT, encoding: 'utf8', env, timeout: 60_000 });
    expect(ok.status, ok.stderr).toBe(0);
    fs.appendFileSync(path.join(dir, '122a_step_optimization_appendix.md'), '\n| R-ZQ | a new rule in a historical spec | x |\n');
    const bad = spawnSync('node', [CHECKER, '--check'], { cwd: REPO_ROOT, encoding: 'utf8', env, timeout: 60_000 });
    expect(bad.status, bad.stdout).toBe(1);
    expect(bad.stderr).toContain('arm(vii)');
    expect(bad.stderr).toContain('new rule id R-ZQ in a historical spec');
  });
});
